    "Echte Ereignisse aus Evidence, MHX-Netzwerktreffern und XDR-Findings werden zusammengeführt.": "Real events from evidence, MHX network matches and XDR findings are merged.",
    "Echte Freigaben aus der Windows App-Control-Schicht. Hinzufügen und Entfernen wird als protokollierte Sicherheits-Transaktion ausgeführt.": "Real permits from the Windows App Control layer. Adding and removing are performed as a logged security transaction.",
    "Echte Windows-Firewall-Programmregeln (ausgehend und eingehend, Aktion Block). Der Pfad wird serverseitig validiert, gehasht und als Sicherheits-Transaktion protokolliert.": "Real Windows Firewall program rules (outbound and inbound, action Block). The path is validated and hashed server-side and logged as a security transaction.",
