    "Echtzeit-Traffic, Download und Upload der letzten 120 Sekunden": "Realtime traffic, download and upload over the last 120 seconds",
    "Eigene Benachrichtigungen für echte Blocker": "Custom notifications for real blocks",
    "Eigener Standort nicht aus lokalen Schnittstellen / CSV bestimmbar. Hinter NAT optional GEDEFENSE_MAP_HOST_IP konfigurieren.": "Own location cannot be determined from local interfaces / CSV. Behind NAT, optionally configure GEDEFENSE_MAP_HOST_IP.",
    "Eigener Standort: {place}": "Own location: {place}",
    "Eigener öffentlicher Standort unbekannt (z. B. NAT). Quellen bleiben sichtbar; keine erfundene Zielposition.": "Own public location unknown (e.g. NAT). Sources remain visible; no invented target position.",
    "Eigenes Schutzprofil entwerfen": "Design a custom protection profile",
    "Ein Neustart kann erforderlich sein.": "A restart may be required.",
    "Ein Profil bündelt eine Basisstufe und ausgewählte Kontrollen. Entwürfe bleiben lokal in dieser Sitzung; das Anwenden benötigt die serverseitige V5-Settings-API.": "A profile bundles a base level and selected controls. Drafts remain local to this session; applying requires the server-side V5 settings API.",
    "Ein alter oder leerer Feed ist ein Betriebsproblem, kein Beweis für einen Angriff. WFP-Blocksperren werden nur als Schutzwirkung gewertet, wenn die aktive Regelgeneration verifiziert ist und zur Datenbasis passt.": "An old or empty feed is an operational issue, not proof of an attack. WFP blocks count as protection only if the active rule generation is verified and matches the dataset.",
    "Ein zeitlich naher Prozess- oder Netzwerkbezug wird als": "A closely timed process or network relation is treated as",
    "Eine Freigabe gilt nur für einen konkreten Pfad, optional einen Hash, eine Aktion und einen Ablauf. Sie ersetzt keine pauschale Admin-Freigabe.": "A permit applies only to a specific path, optionally a hash, an action and an expiry. It does not replace blanket admin approval.",
    "Eine Schutzlage. Alle Windows-Schichten.": "One security posture. Every Windows layer.",
    "Eine Wiederherstellung prüft den gespeicherten SHA-256-Wert und überschreibt niemals ein bereits vorhandenes Ziel. Jede Entscheidung wird als eigenes Evidenzereignis protokolliert.": "A restoration verifies the stored SHA-256 value and never overwrites an existing target. Every decision is logged as a separate evidence event.",
