    "Titan Control Center": "Titan Control Center",
    "Titan beobachtet Veränderungen, die keiner akuten Freigabe bedürfen. Die Evidenzkette bleibt prüfbar.": "Titan observes changes that do not require an immediate permit. The evidence chain remains auditable.",
    "Titan bewertet gemessene Werte, nicht die Behauptung eines Administrators.": "Titan evaluates measured values, not an administrator's claim.",
    "Titan erfindet keine Beobachtungen. Wähle einen anderen Filter oder warte auf reale Sensorereignisse.": "Titan does not invent observations. Choose another filter or wait for real sensor events.",
    "Titan hat mindestens eine Veränderung ohne gültige Freigabe beobachtet. Die Aktion bleibt bis zur Besitzerentscheidung sichtbar.": "Titan observed at least one change without a valid permit. The action remains visible until the owner decides.",
    "Titan isoliert nur nach einer Richtlinie oder einer ausdrücklichen Besitzerentscheidung.": "Titan isolates only under a policy or an explicit owner decision.",
    "Titan legt eine verschlüsselte Beweiskopie an und entfernt das Original nach erfolgreicher Prüfung. Die Ausführung wird nicht nachträglich beendet.": "Titan creates an encrypted evidence copy and removes the original after successful verification. Execution is not terminated afterward.",
    "Titan liefert keine erfundene Abdeckung. Prüfe den Dienststatus.": "Titan does not report fabricated coverage. Check the service status.",
    "Titan liest die lokale Evidenzkette und die Sensorgesundheit.": "Titan reads the local evidence chain and sensor health.",
    "Titan markiert bis zu 100 sichtbare offene Befunde als geprüft. Die Ereignisse bleiben unverändert in der Evidenzkette; es wird keine Datei gelöscht oder umgeschrieben.": "Titan marks up to 100 visible open findings as reviewed. The events remain unchanged in the evidence chain; no file is deleted or rewritten.",
