    "Titan nicht erreichbar: {0}": "Titan unreachable: {0}",
    "Titan prüft den SHA-256-Wert und stellt das Objekt nur wieder her, wenn das Originalziel frei ist. Jede Entscheidung wird protokolliert.": "Titan verifies the SHA-256 value and restores the object only if the original target is free. Every decision is logged.",
    "Titan sichert zuerst eine verschlüsselte Beweiskopie und entfernt das Original nur nach erfolgreicher Integritätsprüfung.": "Titan first secures an encrypted evidence copy and removes the original only after successful integrity verification.",
    "Titan signiert die Evidenzkette automatisch nach den ersten Ereignissen oder beim nächsten Prüflauf.": "Titan signs the evidence chain automatically after the first events or on the next check run.",
