    "EVIDENZPAKET": "ПАКЕТ ДОКАЗАТЕЛЬСТВ",
    "Echte Ereignisse aus Evidence, MHX-Netzwerktreffern und XDR-Findings werden zusammengeführt.": "Реальные события из доказательств, сетевых совпадений MHX и находок XDR объединяются.",
    "Echte Freigaben aus der Windows App-Control-Schicht. Hinzufügen und Entfernen wird als protokollierte Sicherheits-Transaktion ausgeführt.": "Реальные разрешения из уровня Windows App Control. Добавление и удаление выполняются как протоколируемая транзакция безопасности.",
    "Echte Windows-Firewall-Programmregeln (ausgehend und eingehend, Aktion Block). Der Pfad wird serverseitig validiert, gehasht und als Sicherheits-Transaktion protokolliert.": "Реальные программные правила брандмауэра Windows (исходящие и входящие, действие «Блок»). Путь проверяется на стороне сервера, хешируется и протоколируется как транзакция безопасности.",
    "Echtzeit-Traffic": "Трафик в реальном времени",
    "Echtzeit-Traffic, Download und Upload der letzten 120 Sekunden": "Трафик в реальном времени, загрузка и отправка за последние 120 секунд",
    "Eigene Benachrichtigungen für echte Blocker": "Собственные уведомления для реальных блокировок",
    "Eigener Standort nicht aus lokalen Schnittstellen / CSV bestimmbar. Hinter NAT optional GEDEFENSE_MAP_HOST_IP konfigurieren.": "Собственное расположение нельзя определить по локальным интерфейсам / CSV. За NAT при необходимости настройте GEDEFENSE_MAP_HOST_IP.",
    "Eigener Standort: {place}": "Собственное местоположение: {place}",
    "Eigener öffentlicher Standort unbekannt (z. B. NAT). Quellen bleiben sichtbar; keine erfundene Zielposition.": "Собственное публичное местоположение неизвестно (например, NAT). Источники остаются видимыми; вымышленное положение цели не используется.",
    "Eigenes Schutzprofil entwerfen": "Создать собственный профиль защиты",
    "Ein Neustart kann erforderlich sein.": "Может потребоваться перезапуск.",
    "Ein Profil bündelt eine Basisstufe und ausgewählte Kontrollen. Entwürfe bleiben lokal in dieser Sitzung; das Anwenden benötigt die serverseitige V5-Settings-API.": "Профиль объединяет базовый уровень и выбранные меры контроля. Черновики остаются локальными в этой сессии; для применения нужен серверный API настроек V5.",
    "Ein alter oder leerer Feed ist ein Betriebsproblem, kein Beweis für einen Angriff. WFP-Blocksperren werden nur als Schutzwirkung gewertet, wenn die aktive Regelgeneration verifiziert ist und zur Datenbasis passt.": "Устаревший или пустой поток — это эксплуатационная проблема, а не доказательство атаки. Блокировки WFP учитываются как защитный эффект только тогда, когда активная генерация правил подтверждена и соответствует базе данных.",
    "Ein zeitlich naher Prozess- oder Netzwerkbezug wird als": "Близкая по времени связь с процессом или сетью считается",
    "Eine Freigabe gilt nur für einen konkreten Pfad, optional einen Hash, eine Aktion und einen Ablauf. Sie ersetzt keine pauschale Admin-Freigabe.": "Разрешение действует только для конкретного пути, необязательного хеша, действия и срока. Оно не заменяет общее разрешение администратора.",
    "Eine Schutzlage. Alle Windows-Schichten.": "Единая картина защиты. Все уровни Windows.",
    "Eine Wiederherstellung prüft den gespeicherten SHA-256-Wert und überschreibt niemals ein bereits vorhandenes Ziel. Jede Entscheidung wird als eigenes Evidenzereignis protokolliert.": "Восстановление проверяет сохраненное значение SHA-256 и никогда не перезаписывает уже существующую цель. Каждое решение протоколируется как отдельное событие-доказательство.",
    "Eingehende RDP-Sitzungen werden blockiert.": "Входящие сессии RDP блокируются.",
