    "GET {0} ist noch nicht erreichbar. Angezeigt wird lokal aus dem begrenzten Snapshot (maximal 100 Einträge). Die Seitenzahlen beziehen sich nur auf diesen Ausschnitt.": "GET {0} пока недоступен. Данные отображаются локально из ограниченного снимка (не более 100 записей). Номера страниц относятся только к этому фрагменту.",
