    "GeDefense ist bereit": "GeDefense готов",
    "GeDefense misst Defender, Firewall, Telemetrie und Threat Intelligence. MHX bewertet Prozesse, beendet aber keine Prozesse. Die Schutzlage ist sichtbar, ohne dass die Control Plane eingreift.": "GeDefense измеряет Defender, брандмауэр, телеметрию и разведку угроз. MHX оценивает процессы, но не завершает их. Картина защиты видна без вмешательства плоскости управления.",
    "GeDefense nutzt Windows-eigene TCP-Tabellen und verbindet Threat-Intel-Treffer ohne zusätzliche Runtime mit MHX.": "GeDefense использует собственные TCP-таблицы Windows и связывает совпадения Threat Intel с MHX без дополнительной среды выполнения.",
    "GeDefense wendet die idempotente Enterprise-Balanced-Härtung an. Jede Änderung wird als Sicherheits-Transaktion protokolliert und ist reversibel.": "GeDefense применяет идемпотентное усиление Enterprise Balanced. Каждое изменение протоколируется как транзакция безопасности и обратимо.",
