    "Grund: {0} · Die Live-Korrelation und die Bedienung oben bleiben nutzbar. Es werden keine Schwellenwerte simuliert.": "Причина: {0} · Корреляция в реальном времени и управление выше остаются доступны. Пороговые значения не симулируются.",
    "Grund: {0} · Die Live-Telemetrie und der Tiefenscan bleiben nutzbar. Es werden keine Werte simuliert.": "Причина: {0} · Телеметрия в реальном времени и глубокое сканирование остаются доступны. Значения не симулируются.",
    "Größe": "Размер",
    "Guarded aktiv, verifizierte TI-Blockabdeckung und verifizierte WFP-Generation erforderlich.": "Защищенный режим активен; требуются подтвержденное покрытие блокировок TI и подтвержденная генерация WFP.",
    "Guarded erlaubt MHX, einen als blockierend bewerteten Prozess nach erneuter Prüfung von Signatur, Herkunft und Prozessidentität zu beenden. Die Schutzrichtlinie muss serverseitig verifiziert sein.": "Защищенный режим позволяет MHX завершать процесс, оцененный как блокирующий, после повторной проверки подписи, происхождения и идентичности процесса. Политика защиты должна быть подтверждена на стороне сервера.",
    "Guarded — kontextuelle Response": "Защищенный — контекстный отклик",
