    "HMAC-verkettete Security-Ereignisse machen nachträgliche Manipulation detektierbar. Angezeigt werden seitenweise die neuesten Einträge; es gibt keine endlose Liste.": "События безопасности, связанные HMAC, позволяют обнаружить последующую подмену. Отображаются последние записи постранично; бесконечного списка нет.",
