    "In diesem owner-markierten Baum bleiben Dateiereignisse vollständig in der Evidenz, werden aber nicht als Ingress-Hochrisiko eskaliert. System-/Persistenzänderungen bleiben unverändert streng.": "В этом дереве, отмеченном владельцем, файловые события полностью сохраняются в доказательствах, но не повышаются до высокого риска входящего трафика. Изменения системы и закрепления остаются строгими без изменений.",
