    "Jede Änderung": "Каждое изменение",
    "Jede Änderung an diesem Pfad": "Любое изменение этого пути",
    "Jede Änderung wird gegen deine Owner-Policy geprüft: autorisiert, geduldet oder unerwartet. Titan zeigt, wie sie beobachtet wurde und welcher unabhängige Beleg bleibt. Detect. Verify. Contain. Preserve.": "Каждое изменение проверяется по вашей политике владельца: авторизовано, допущено или неожиданно. Titan показывает, как оно наблюдалось и какое независимое доказательство остается. Обнаружение. Проверка. Изоляция. Сохранение.",
    "Jeder Checkpoint bindet die bisherige Journal-Kette an einen Ed25519-Schlüssel. Die Signatur schützt die Kette; sie beweist keine Urheberschaft.": "Каждая контрольная точка привязывает текущую цепочку журнала к ключу Ed25519. Подпись защищает цепочку; она не доказывает авторство.",
    "Jeder Feed hat eine klare Rolle. Änderungen werden serverseitig validiert, persistiert und erst nach verifizierter WFP-Generation als aktive Sperrwirkung ausgewiesen.": "У каждого потока есть четкая роль. Изменения проверяются на стороне сервера, сохраняются и признаются активным блокирующим эффектом только после подтвержденной генерации WFP.",
