    "Keine Anwendung ist aktuell per Windows-Firewall vom Netzwerk ausgeschlossen.": "Сейчас ни одно приложение не исключено из сети через брандмауэр Windows.",
    "Keine Anwendungsfreigaben hinterlegt. Die App-Control-Schicht kann keine zusätzlichen Anwendungen zulassen.": "Разрешения приложений не заданы. Уровень App Control не может разрешить дополнительные приложения.",
