    "Keine direkte Zuordnung": "Нет прямого сопоставления",
    "Keine eigenständigen Kinetic-Sperrregeln. Windows Threat-Intel-WFP-Blockregeln werden nur nach geprüfter Generation als Schutzwirkung gewertet.": "Собственных правил блокировки Kinetic нет. Правила блокировки Windows Threat Intel WFP учитываются как защитный эффект только после проверенной генерации.",
