    "Read-only Audit läuft. Die Control Plane misst Windows-Kontrollen; das kann bis zu fünf Minuten dauern.": "Выполняется аудит только для чтения. Плоскость управления измеряет меры контроля Windows; это может занять до пяти минут.",
    "Read-only Audit-Transaktion anfordern; keine Einstellungen ändern.": "Запросить транзакцию аудита только для чтения; не изменять настройки.",
    "Read-only Prüfung der lokalen Defender-, Netzwerk-, Plattform-, Identitäts-, Logging- und Systemkontrollen. Der Lauf zeigt sofort einen Dialog mit Stufe und Laufzeit; es gibt kein stilles Warten.": "Проверка только для чтения локальных мер контроля Defender, сети, платформы, идентичности, журналирования и системы. Запуск сразу показывает диалог с уровнем и длительностью; без скрытого ожидания.",
    "Read-only Windows-Baseline-Audit mit sofortigem Fortschritts-Feedback.": "Аудит базовой линии Windows только для чтения с немедленным отображением хода выполнения.",
