    "Threat Intelligence Synchronisation": "Синхронизация разведки угроз",
    "Threat Intelligence ist eine eigene Betriebsfläche: Feed-Zustand, letzte Synchronisation, nächster Abruf, konfigurierbares Intervall und geschützte Management-Prefixe. Keine externen IP-Abfragen im Browser.": "Разведка угроз — отдельная рабочая область: состояние потоков, последняя синхронизация, следующий запрос, настраиваемый интервал и защищенные префиксы управления. Без внешних IP-запросов в браузере.",
