    "Titan": "Titan",
    "Titan Bereiche": "Области Titan",
    "Titan Control Center": "Центр управления Titan",
    "Titan beobachtet Veränderungen, die keiner akuten Freigabe bedürfen. Die Evidenzkette bleibt prüfbar.": "Titan наблюдает изменения, не требующие срочного разрешения. Цепочка доказательств остается проверяемой.",
    "Titan bewertet gemessene Werte, nicht die Behauptung eines Administrators.": "Titan оценивает измеренные значения, а не утверждения администратора.",
    "Titan erfindet keine Beobachtungen. Wähle einen anderen Filter oder warte auf reale Sensorereignisse.": "Titan не выдумывает наблюдения. Выберите другой фильтр или дождитесь реальных событий датчиков.",
    "Titan hat mindestens eine Veränderung ohne gültige Freigabe beobachtet. Die Aktion bleibt bis zur Besitzerentscheidung sichtbar.": "Titan обнаружил как минимум одно изменение без действительного разрешения. Действие остается видимым до решения владельца.",
    "Titan isoliert nur nach einer Richtlinie oder einer ausdrücklichen Besitzerentscheidung.": "Titan изолирует только по политике или явному решению владельца.",
    "Titan legt eine verschlüsselte Beweiskopie an und entfernt das Original nach erfolgreicher Prüfung. Die Ausführung wird nicht nachträglich beendet.": "Titan создает зашифрованную копию-доказательство и удаляет оригинал после успешной проверки. Выполнение задним числом не завершается.",
    "Titan liefert keine erfundene Abdeckung. Prüfe den Dienststatus.": "Titan не показывает вымышленное покрытие. Проверьте состояние службы.",
    "Titan liest die lokale Evidenzkette und die Sensorgesundheit.": "Titan считывает локальную цепочку доказательств и состояние датчиков.",
    "Titan markiert bis zu 100 sichtbare offene Befunde als geprüft. Die Ereignisse bleiben unverändert in der Evidenzkette; es wird keine Datei gelöscht oder umgeschrieben.": "Titan отмечает до 100 видимых открытых находок как проверенные. События остаются неизменными в цепочке доказательств; ни один файл не удаляется и не перезаписывается.",
    "Titan nicht erreichbar": "Titan недоступен",
    "Titan nicht erreichbar: {0}": "Titan недоступен: {0}",
    "Titan prüft den SHA-256-Wert und stellt das Objekt nur wieder her, wenn das Originalziel frei ist. Jede Entscheidung wird protokolliert.": "Titan проверяет значение SHA-256 и восстанавливает объект только при свободной исходной цели. Каждое решение протоколируется.",
    "Titan sichert zuerst eine verschlüsselte Beweiskopie und entfernt das Original nur nach erfolgreicher Integritätsprüfung.": "Titan сначала сохраняет зашифрованную копию-доказательство и удаляет оригинал только после успешной проверки целостности.",
    "Titan signiert die Evidenzkette automatisch nach den ersten Ereignissen oder beim nächsten Prüflauf.": "Titan автоматически подписывает цепочку доказательств после первых событий или при следующем прогоне проверки.",
    "Titan-Evidenz konnte nicht verifiziert werden.": "Не удалось подтвердить доказательства Titan.",
