    "ERROR": "ERROR",
    "EVIDENCE LEDGER": "证据台账",
    "EVIDENZPAKET": "证据包",
    "Echte Ereignisse aus Evidence, MHX-Netzwerktreffern und XDR-Findings werden zusammengeführt.": "将来自证据、MHX 网络命中与 XDR 发现的真实事件汇总。",
    "Echte Freigaben aus der Windows App-Control-Schicht. Hinzufügen und Entfernen wird als protokollierte Sicherheits-Transaktion ausgeführt.": "来自 Windows App Control 层的真实许可。添加与移除都作为可记录的安全事务执行。",
    "Echte Windows-Firewall-Programmregeln (ausgehend und eingehend, Aktion Block). Der Pfad wird serverseitig validiert, gehasht und als Sicherheits-Transaktion protokolliert.": "真实的 Windows 防火墙程序规则（出站与入站，操作为拦截）。路径在服务器端验证、计算哈希，并记录为安全事务。",
    "Echtzeit-Traffic": "实时流量",
    "Echtzeit-Traffic, Download und Upload der letzten 120 Sekunden": "最近 120 秒的实时流量、下载与上传",
    "Eigene Benachrichtigungen für echte Blocker": "仅针对真实拦截的自定义通知",
    "Eigener Standort nicht aus lokalen Schnittstellen / CSV bestimmbar. Hinter NAT optional GEDEFENSE_MAP_HOST_IP konfigurieren.": "无法从本地接口/CSV 确定本机位置。位于 NAT 后方时，可选择配置 GEDEFENSE_MAP_HOST_IP。",
    "Eigener Standort: {place}": "本机位置：{place}",
    "Eigener öffentlicher Standort unbekannt (z. B. NAT). Quellen bleiben sichtbar; keine erfundene Zielposition.": "本机公网位置未知（例如 NAT）。来源仍可见；不会虚构目标位置。",
    "Eigenes Schutzprofil entwerfen": "设计自定义防护配置文件",
    "Ein Neustart kann erforderlich sein.": "可能需要重启。",
    "Ein Profil bündelt eine Basisstufe und ausgewählte Kontrollen. Entwürfe bleiben lokal in dieser Sitzung; das Anwenden benötigt die serverseitige V5-Settings-API.": "一个配置文件包含基础级别和所选控制项。草稿仅保留在本会话本地；应用需要服务器端 V5 设置 API。",
    "Ein alter oder leerer Feed ist ein Betriebsproblem, kein Beweis für einen Angriff. WFP-Blocksperren werden nur als Schutzwirkung gewertet, wenn die aktive Regelgeneration verifiziert ist und zur Datenbasis passt.": "陈旧或为空的情报源属于运营问题，而不是攻击的证据。只有当活动规则代次通过验证且与数据基线匹配时，WFP 拦截才会被计为防护效果。",
    "Ein zeitlich naher Prozess- oder Netzwerkbezug wird als": "时间上接近的进程或网络关联将被视为",
    "Eine Freigabe gilt nur für einen konkreten Pfad, optional einen Hash, eine Aktion und einen Ablauf. Sie ersetzt keine pauschale Admin-Freigabe.": "许可仅对特定路径、可选哈希、一项操作和有效期生效。它不能替代笼统的管理员放行。",
    "Eine Schutzlage. Alle Windows-Schichten.": "一个防护态势。所有 Windows 层次。",
    "Eine Wiederherstellung prüft den gespeicherten SHA-256-Wert und überschreibt niemals ein bereits vorhandenes Ziel. Jede Entscheidung wird als eigenes Evidenzereignis protokolliert.": "恢复时会校验保存的 SHA-256 值，绝不会覆盖已存在的目标。每次决策都会作为独立的证据事件记录。",
    "Eingehende RDP-Sitzungen werden blockiert.": "入站 RDP 会话将被拦截。",
    "Einige Bereiche benötigen Aufmerksamkeit": "部分区域需要关注",
