    "Ergebnisse erscheinen nach einem abgeschlossenen Audit. Ein neuer Lauf ersetzt die Anzeige, nicht die lokale Evidenz.": "结果在审计完成后显示。新的运行只会替换显示内容，不会替换本地证据。",
