    "GeDefense misst Defender, Firewall, Telemetrie und Threat Intelligence. MHX bewertet Prozesse, beendet aber keine Prozesse. Die Schutzlage ist sichtbar, ohne dass die Control Plane eingreift.": "GeDefense 测量 Defender、防火墙、遥测和威胁情报。MHX 评估进程，但不终止进程。防护态势可见，而控制平面无需介入。",
    "GeDefense nutzt Windows-eigene TCP-Tabellen und verbindet Threat-Intel-Treffer ohne zusätzliche Runtime mit MHX.": "GeDefense 使用 Windows 原生 TCP 表，无需额外运行时即可将威胁情报命中与 MHX 关联。",
