    "Jede Änderung wird gegen deine Owner-Policy geprüft: autorisiert, geduldet oder unerwartet. Titan zeigt, wie sie beobachtet wurde und welcher unabhängige Beleg bleibt. Detect. Verify. Contain. Preserve.": "每次变更都会对照你的所有者策略进行检查：已授权、被容忍或异常。Titan 会显示它是如何被观察到的，以及留下了哪些独立证据。检测。验证。遏制。留存。",
    "Jeder Checkpoint bindet die bisherige Journal-Kette an einen Ed25519-Schlüssel. Die Signatur schützt die Kette; sie beweist keine Urheberschaft.": "每个检查点将现有日志链绑定到 Ed25519 密钥。签名保护该链；但不证明来源归属。",
