    "Titan Bereiche": "Titan 领域",
    "Titan Control Center": "Titan 控制中心",
    "Titan beobachtet Veränderungen, die keiner akuten Freigabe bedürfen. Die Evidenzkette bleibt prüfbar.": "Titan 观察无需即时许可的变更。证据链保持可核查。",
    "Titan bewertet gemessene Werte, nicht die Behauptung eines Administrators.": "Titan 评估的是实测值，而非管理员的自述。",
    "Titan erfindet keine Beobachtungen. Wähle einen anderen Filter oder warte auf reale Sensorereignisse.": "Titan 不会虚构观察结果。请更换筛选条件，或等待真实传感器事件。",
    "Titan hat mindestens eine Veränderung ohne gültige Freigabe beobachtet. Die Aktion bleibt bis zur Besitzerentscheidung sichtbar.": "Titan 观察到至少一处变更没有有效许可。在所有者作出决定前，该操作始终可见。",
    "Titan isoliert nur nach einer Richtlinie oder einer ausdrücklichen Besitzerentscheidung.": "Titan 仅依据策略或所有者的明确决定进行隔离。",
    "Titan legt eine verschlüsselte Beweiskopie an und entfernt das Original nach erfolgreicher Prüfung. Die Ausführung wird nicht nachträglich beendet.": "Titan 创建加密证据副本，并在校验成功后移除原始文件。不会事后终止正在运行的进程。",
    "Titan liefert keine erfundene Abdeckung. Prüfe den Dienststatus.": "Titan 不会虚构覆盖范围。请检查服务状态。",
    "Titan liest die lokale Evidenzkette und die Sensorgesundheit.": "Titan 读取本地证据链与传感器健康状况。",
    "Titan markiert bis zu 100 sichtbare offene Befunde als geprüft. Die Ereignisse bleiben unverändert in der Evidenzkette; es wird keine Datei gelöscht oder umgeschrieben.": "Titan 最多将 100 项可见的未处理发现标记为已检查。事件在证据链中保持不变；不会删除或重写任何文件。",
    "Titan nicht erreichbar": "无法连接 Titan",
    "Titan nicht erreichbar: {0}": "Titan 无法访问：{0}",
    "Titan prüft den SHA-256-Wert und stellt das Objekt nur wieder her, wenn das Originalziel frei ist. Jede Entscheidung wird protokolliert.": "Titan 校验 SHA-256 值，仅在原目标路径空闲时才恢复对象。每次决策都会被记录。",
    "Titan sichert zuerst eine verschlüsselte Beweiskopie und entfernt das Original nur nach erfolgreicher Integritätsprüfung.": "Titan 会先保存加密的证据副本，仅在完整性校验成功后才移除原始文件。",
    "Titan signiert die Evidenzkette automatisch nach den ersten Ereignissen oder beim nächsten Prüflauf.": "Titan 会在首批事件后或下次检查运行时自动签名证据链。",
